insert into passages (title,body,"wordCount",difficulty,topic,status) values ('Feedback in Learning', 'Feedback is useful only when learners understand how to act on it. A comment such as “improve your writing” may be accurate, but it gives little direction. More effective feedback identifies a specific weakness and suggests a next step. This helps learners focus their effort and reduces frustration. In this sense, feedback is not simply evaluation; it is guidance for future performance. The discussion is framed around a realistic situation in which readers must distinguish the central claim from tempting but exaggerated conclusions.', 83, 7, 'feedback', 'approved');
